height = float(input("키(cm): "))
weight = float(input("몸무게(kg): "))
h_m = height / 100
bmi = weight / (h_m * h_m)

print(f"BMI: {bmi:.2f}")
if bmi < 18.5:
    print("저체중")
elif bmi < 23.0:
    print("정상체중")
elif bmi < 25.0:
    print("과체중")
else:
    print("비만")

